'use client';

import { Collapsible as CollapsiblePrimitive } from '@base-ui/react/collapsible';
import { AnimatePresence, type HTMLMotionProps, motion, type Transition } from 'motion/react';
import React from 'react';

import { asChildToRender, asChildTrigger, splitMotionProps } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const DEFAULT_TRANSITION = { damping: 22, stiffness: 150, type: 'spring' } satisfies Transition;

interface CollapsibleContextType {
  isOpen: boolean;
}

const CollapsibleContext = React.createContext<boolean | undefined>(undefined);

const useCollapsible = (): CollapsibleContextType => {
  const context = React.useContext(CollapsibleContext);
  if (context === undefined) {
    throw new Error('useCollapsible must be used within a Collapsible');
  }
  return { isOpen: context };
};

type CollapsibleProps = React.ComponentProps<typeof CollapsiblePrimitive.Root> &
  SharedProps & {
    asChild?: boolean;
  };

function Collapsible({ children, testId, asChild, onOpenChange, open, defaultOpen, ...props }: CollapsibleProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false);
  const isOpen = open ?? uncontrolledOpen;

  const handleOpenChange: NonNullable<CollapsiblePrimitive.Root.Props['onOpenChange']> = (nextOpen, details) => {
    onOpenChange?.(nextOpen, details);
    if (details.isCanceled) {
      return;
    }
    if (open === undefined) {
      setUncontrolledOpen(nextOpen);
    }
  };

  return (
    <CollapsibleContext.Provider value={isOpen}>
      <CollapsiblePrimitive.Root
        data-slot="collapsible"
        data-testid={testId}
        {...props}
        defaultOpen={defaultOpen}
        open={open}
        {...asChildToRender({ asChild, children })}
        onOpenChange={handleOpenChange}
      />
    </CollapsibleContext.Provider>
  );
}

type CollapsibleTriggerProps = React.ComponentProps<typeof CollapsiblePrimitive.Trigger> & {
  asChild?: boolean;
};

function CollapsibleTrigger({ className, ...props }: CollapsibleTriggerProps) {
  return (
    <CollapsiblePrimitive.Trigger
      className={(state) => cn('cursor-pointer', typeof className === 'function' ? className(state) : className)}
      data-slot="collapsible-trigger"
      {...asChildTrigger(props)}
    />
  );
}

type CollapsibleContentProps = React.ComponentProps<typeof CollapsiblePrimitive.Panel> &
  Omit<HTMLMotionProps<'div'>, keyof React.ComponentProps<typeof CollapsiblePrimitive.Panel>> & {
    transition?: Transition;
  };

function CollapsibleContent({
  className,
  children,
  render,
  keepMounted = false,
  transition = DEFAULT_TRANSITION,
  ...props
}: CollapsibleContentProps) {
  const { isOpen } = useCollapsible();
  const separated = splitMotionProps(props);

  return (
    <AnimatePresence>
      {isOpen || keepMounted === true ? (
        <CollapsiblePrimitive.Panel
          className={className}
          data-slot="collapsible-content"
          keepMounted
          render={render}
          {...separated.native}
        >
          <motion.div
            animate={{ height: 'auto', opacity: 1, overflow: 'hidden' }}
            exit={{ height: 0, opacity: 0, overflow: 'hidden' }}
            initial={{ height: 0, opacity: 0, overflow: 'hidden' }}
            layout
            transition={transition}
            {...separated.motion}
          >
            {children}
          </motion.div>
        </CollapsiblePrimitive.Panel>
      ) : null}
    </AnimatePresence>
  );
}

export {
  Collapsible,
  CollapsibleContent,
  type CollapsibleContentProps,
  type CollapsibleContextType,
  type CollapsibleProps,
  CollapsibleTrigger,
  type CollapsibleTriggerProps,
  useCollapsible,
};

import { isValidMotionProp, type MotionProps } from 'motion/react';
import React from 'react';

type HTMLPropsCompat<T = Element> = React.HTMLAttributes<T> & {
  ref?: React.Ref<T> | undefined;
};

type ComponentRenderFnCompat<Props, State> = (props: Props, state: State) => React.ReactElement;

interface AsChildInput {
  asChild?: boolean | undefined;
  children?: React.ReactNode | undefined;
}

export function asChildToRender<P extends AsChildInput>(props: P): Omit<P, 'asChild'> {
  const { asChild, children, ...rest } = props;
  if (asChild === true && React.isValidElement(children)) {
    return { ...rest, render: children } as unknown as Omit<P, 'asChild'>;
  }
  return { ...rest, children } as Omit<P, 'asChild'>;
}

function compatStateAttrs(state: CompatState | undefined): Record<string, string> {
  const attrs: Record<string, string> = {};
  if (state && typeof state.open === 'boolean') {
    attrs['data-state'] = state.open === true ? 'open' : 'closed';
  }
  if (state?.checked !== undefined) {
    if (state.checked === 'indeterminate') {
      attrs['data-state'] = 'indeterminate';
    } else if (typeof state.checked === 'boolean') {
      attrs['data-state'] = state.checked === true ? 'checked' : 'unchecked';
    }
  }
  if (state?.disabled === true) {
    attrs['data-disabled'] = '';
  }
  return attrs;
}

export function asChildTrigger<P extends AsChildInput>(props: P): Omit<P, 'asChild'> & { nativeButton?: boolean } {
  const base = asChildToRender(props);
  if (props.asChild !== true) {
    return base;
  }
  const child = props.children;
  if (!React.isValidElement(child)) {
    return base;
  }
  if (rendersNonButton(child)) {
    return { ...base, nativeButton: false };
  }
  return base;
}

function rendersNonButton(element: React.ReactElement): boolean {
  if (typeof element.type === 'string') {
    return element.type !== 'button';
  }
  const props = (element.props ?? {}) as { asChild?: boolean; children?: React.ReactNode };
  if (props.asChild !== true) {
    return false;
  }
  const inner = React.Children.count(props.children) === 1 ? React.Children.only(props.children) : null;
  return React.isValidElement(inner) ? rendersNonButton(inner) : false;
}

export interface CompatState {
  checked?: boolean | 'indeterminate';
  disabled?: boolean;
  open?: boolean;
}

export function renderWithDataState<S extends CompatState = CompatState>(
  Element: keyof React.JSX.IntrinsicElements = 'div'
): ComponentRenderFnCompat<HTMLPropsCompat, S> {
  return function renderDataState(props, state) {
    return React.createElement(Element, { ...props, ...compatStateAttrs(state) });
  };
}

export function narrowOpenChange<Details>(
  handler: ((open: boolean) => void) | undefined
): ((open: boolean, details: Details) => void) | undefined {
  if (!handler) {
    return;
  }
  return (open: boolean) => {
    handler(open);
  };
}

export function narrowCallback<Value, Details>(
  handler: ((value: Value) => void) | undefined
): ((value: Value, details: Details) => void) | undefined {
  if (!handler) {
    return;
  }
  return (value: Value) => {
    handler(value);
  };
}

export type BaseUIMouseEvent<T = HTMLElement> = React.MouseEvent<T> & {
  preventBaseUIHandler: () => void;
  readonly baseUIHandlerPrevented?: boolean | undefined;
};

export function useMirroredOpen<Details extends { isCanceled: boolean }>(
  controlledOpen: boolean | undefined,
  defaultOpen: boolean | undefined,
  onOpenChange: ((open: boolean, details: Details) => void) | undefined
) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false);
  const isOpen = controlledOpen ?? uncontrolledOpen;
  const handleOpenChange = (open: boolean, details: Details) => {
    onOpenChange?.(open, details);
    if (!details.isCanceled && controlledOpen === undefined) {
      setUncontrolledOpen(open);
    }
  };
  return { handleOpenChange, isOpen };
}

interface DescriptionRenderProps {
  asChild?: boolean | undefined;
  children?: React.ReactNode | undefined;
  className?: string | undefined;
  dataSlot?: string | undefined;
  fallbackClassName?: string | undefined;
}

export function renderDescription({
  asChild,
  children,
  className,
  fallbackClassName = 'text-muted-foreground text-sm',
  dataSlot,
}: DescriptionRenderProps): React.ReactElement {
  if (asChild === true && React.isValidElement<{ 'data-slot'?: string }>(children)) {
    if (!(dataSlot !== undefined && dataSlot !== '')) {
      return children;
    }
    if (children.props['data-slot']) {
      return children;
    }
    return React.cloneElement(children, { 'data-slot': dataSlot });
  }
  const mergedClassName = [fallbackClassName, className].filter(Boolean).join(' ');
  return <div className={mergedClassName}>{children}</div>;
}

const warnedKeys = new Set<string>();

function isProductionRuntime(): boolean {
  const processValue: unknown = Reflect.get(globalThis, 'process');
  if (!(typeof processValue === 'object' && processValue !== null)) {
    return false;
  }
  const environment: unknown = Reflect.get(processValue, 'env');
  return (
    typeof environment === 'object' && environment !== null && Reflect.get(environment, 'NODE_ENV') === 'production'
  );
}

export function devWarnOnce(key: string, _message: string): void {
  if (isProductionRuntime()) {
    return;
  }
  if (warnedKeys.has(key)) {
    return;
  }
  warnedKeys.add(key);
}

export function resetDevWarnings(): void {
  warnedKeys.clear();
}

export function warnDeprecatedProp(component: string, prop: string, value: unknown, guidance: string): void {
  if (value === undefined) {
    return;
  }
  devWarnOnce(
    `${component}:${prop}`,
    `<${component}> \`${prop}\` is a Radix-compat shim scheduled for removal. ${guidance}`
  );
}

export function resolveKeepMounted(
  component: string,
  forceMount: boolean | undefined,
  keepMounted: boolean | undefined
): boolean | undefined {
  if (forceMount === true) {
    warnDeprecatedProp(
      component,
      'forceMount',
      forceMount,
      'Use `keepMounted` on the underlying Portal instead (already forwarded by this component).'
    );
    return true;
  }
  return keepMounted;
}

type SlotProps = {
  children?: React.ReactNode;
} & React.HTMLAttributes<HTMLElement>;

type SlotElement = React.ReactElement & { ref?: React.Ref<HTMLElement> };

type EventHandler = (...args: unknown[]) => unknown;
const EVENT_HANDLER_KEY_PATTERN = /^on[A-Z]/u;

function isEventHandlerKey(key: string): boolean {
  return EVENT_HANDLER_KEY_PATTERN.test(key);
}

function readHandler(source: object, key: string): EventHandler | undefined {
  const value: unknown = Reflect.get(source, key);
  return typeof value === 'function' ? (value as EventHandler) : undefined;
}

function readString(source: object, key: string): string | undefined {
  const value: unknown = Reflect.get(source, key);
  return typeof value === 'string' ? value : undefined;
}

function readStyle(source: object): React.CSSProperties | undefined {
  const value: unknown = Reflect.get(source, 'style');
  return value !== null && typeof value === 'object' ? value : undefined;
}

function composeRefs<T>(...refs: Array<React.Ref<T> | undefined>): React.RefCallback<T> {
  return (value: T) => {
    for (const ref of refs) {
      if (!ref) {
        continue;
      }
      if (typeof ref === 'function') {
        ref(value);
      } else {
        ref.current = value;
      }
    }
  };
}

function getElementRef(element: React.ReactElement): React.Ref<unknown> | undefined {
  const refFromProps: unknown = Reflect.get(element.props ?? {}, 'ref');
  if (refFromProps !== undefined) {
    return refFromProps as React.Ref<unknown>;
  }
  return (element as SlotElement).ref;
}

function mergeSlotProps(slotProps: object, childProps: object): Record<string, unknown> {
  const merged: Record<string, unknown> = { ...slotProps, ...childProps };

  const slotClass = readString(slotProps, 'className');
  const childClass = readString(childProps, 'className');
  const mergedClass = [slotClass, childClass].filter(Boolean).join(' ');
  if (mergedClass !== '') {
    merged['className'] = mergedClass;
  }

  const slotStyle = readStyle(slotProps);
  const childStyle = readStyle(childProps);
  if (slotStyle || childStyle) {
    merged['style'] = { ...slotStyle, ...childStyle };
  }

  for (const key of Object.keys(slotProps)) {
    if (!isEventHandlerKey(key)) {
      continue;
    }
    const slotHandler = readHandler(slotProps, key);
    const childHandler = readHandler(childProps, key);
    if (slotHandler && childHandler) {
      merged[key] = (...args: unknown[]) => {
        const result = childHandler(...args);
        slotHandler(...args);
        return result;
      };
    } else if (slotHandler) {
      merged[key] = slotHandler;
    }
  }

  return merged;
}

type SlotCloneProps = {
  children: React.ReactNode;
} & React.HTMLAttributes<HTMLElement>;

const SlotClone = React.forwardRef<HTMLElement, SlotCloneProps>(function renderSlotClone(props, forwardedRef) {
  const { children, ...slotProps } = props;

  if (!React.isValidElement(children)) {
    if (React.Children.count(children) > 1) {
      return React.Children.only(null);
    }
    return null;
  }

  const element = children as SlotElement;
  const childProps = element.props ?? {};
  const merged = mergeSlotProps(slotProps, childProps);
  const childRef = getElementRef(element) as React.Ref<HTMLElement> | undefined;
  merged['ref'] = forwardedRef ? composeRefs(forwardedRef, childRef) : childRef;
  return React.cloneElement(element, merged);
});

const SLOTTABLE_IDENTIFIER = Symbol.for('protoform.slottable');

type SlottableComponent = React.FC<{ children: React.ReactNode }> & { __slottableId: symbol };

export const Slottable: SlottableComponent = Object.assign(({ children }: { children: React.ReactNode }) => children, {
  __slottableId: SLOTTABLE_IDENTIFIER,
});
Slottable.displayName = 'Slottable';

function isSlottable(child: React.ReactNode): child is React.ReactElement<{ children: React.ReactNode }> {
  if (!React.isValidElement(child)) {
    return false;
  }
  const componentType: unknown = child.type;
  return (
    (typeof componentType === 'function' || (typeof componentType === 'object' && componentType !== null)) &&
    '__slottableId' in componentType &&
    componentType.__slottableId === SLOTTABLE_IDENTIFIER
  );
}

export const Slot = React.forwardRef<HTMLElement, SlotProps>(function renderSlot(props, forwardedRef) {
  const { children, ...slotProps } = props;
  const childrenArray = React.Children.toArray(children);
  const slottable = childrenArray.find(isSlottable);

  if (slottable !== undefined) {
    const target = slottable.props.children;
    const siblings = childrenArray.map((child) => {
      if (child !== slottable) {
        return child;
      }
      if (React.Children.count(target) > 1) {
        return React.Children.only(null);
      }
      return React.isValidElement<{ children?: React.ReactNode }>(target) ? target.props.children : null;
    });

    return (
      <SlotClone {...slotProps} ref={forwardedRef}>
        {React.isValidElement(target) ? React.cloneElement(target, undefined, siblings) : null}
      </SlotClone>
    );
  }

  return (
    <SlotClone {...slotProps} ref={forwardedRef}>
      {children}
    </SlotClone>
  );
});
Slot.displayName = 'Slot';

type NativeMotionEvent = 'onAnimationStart' | 'onDrag' | 'onDragEnd' | 'onDragStart';
type NativeProps<Props> = Omit<Props, keyof MotionProps> &
  Pick<Props, Extract<keyof Props, NativeMotionEvent | 'style'>>;
const nativeMotionEvents = new Set<string>(['onAnimationStart', 'onDrag', 'onDragEnd', 'onDragStart']);

export function splitMotionProps<Props extends object>(
  props: Props,
  nativeEvents?: true
): { native: NativeProps<Props>; motion: MotionProps };
export function splitMotionProps<Props extends object>(
  props: Props,
  nativeEvents: false
): { native: Omit<Props, keyof MotionProps>; motion: MotionProps };
export function splitMotionProps<Props extends object>(props: Props, nativeEvents = true) {
  const native: Record<string, unknown> = {};
  const motion: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(props) as [string, unknown][]) {
    const target = isValidMotionProp(key) && !(nativeEvents && nativeMotionEvents.has(key)) ? motion : native;
    target[key] = value;
  }
  return { native: native as NativeProps<Props>, motion: motion as MotionProps };
}

import { cva } from 'class-variance-authority';
import { type ClassValue, clsx } from 'clsx';
import type React from 'react';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function wrapStringChild(
  child: React.ReactNode,
  Wrapper: React.ComponentType<{
    children: React.ReactNode;
    className?: string | undefined;
  }>,
  className?: string
): React.ReactNode {
  if (typeof child === 'string') {
    return <Wrapper className={className}>{child}</Wrapper>;
  }
  return child;
}

export interface SharedProps {
  testId?: string | undefined;
}

export interface PortalRootProps {
  defaultOpen?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  open?: boolean | undefined;
}

export type ModalRootProps = PortalRootProps & {
  modal?: boolean | undefined;
};

export interface FocusScopeContentProps {
  onCloseAutoFocus?: ((event: Event) => void) | undefined;
  onOpenAutoFocus?: ((event: Event) => void) | undefined;
}

export type PortalContentProps = FocusScopeContentProps & {
  container?: HTMLElement | undefined;
};

export type FixedPositionContentProps = PortalContentProps & {
  showOverlay?: boolean;
};

export type SemanticVariant = 'success' | 'info' | 'warning' | 'error' | 'disabled';
export type DotSize = 'xxs' | 'xs' | 'sm' | 'md' | 'lg';
export interface StackableProps {
  stacked?: boolean;
}

export const dotColorVariants = cva('', {
  defaultVariants: {
    variant: 'info',
  },
  variants: {
    variant: {
      disabled: 'bg-muted',
      error: 'bg-destructive',
      info: 'bg-primary',
      success: 'bg-primary',
      warning: 'bg-primary',
    },
  },
});

export const dotStackedVariants = cva('!border-background', {
  defaultVariants: {
    size: 'md',
  },
  variants: {
    size: {
      lg: 'border-2',
      md: 'border-2',
      sm: 'border',
      xs: 'border-2',
      xxs: 'border',
    },
  },
});
